(function(){
    function startLenis(){
        // Если включена версия для слабовидящих — отключаем Lenis
        if(document.body.classList.contains('bvi-active') || document.documentElement.classList.contains('bvi-active')){
            if(window.lenisInstance){ try{ window.lenisInstance.destroy(); }catch(e){} window.lenisInstance=null; }
            return;
        }
        if(window.lenisInstance) return;
        if(typeof Lenis === 'undefined') return;
        window.lenisInstance = new Lenis({
            autoRaf: true,
            lerp: 0.1,
            duration: 1.2,
            wheelMultiplier: 1,
            easing: function(x){ return Math.min(1, 1.001 - Math.pow(2, -10 * x)); }
        });
    }
    if(document.readyState === 'loading'){
        document.addEventListener('DOMContentLoaded', startLenis);
    } else {
        startLenis();
    }
    // Если BVI включился/выключился — пересоздаём Lenis
    document.addEventListener('bvi:on', startLenis);
    document.addEventListener('bvi:off', startLenis);
    document.addEventListener('bvi:changed', startLenis);
})();